typedef unsigned char uint8;
typedef unsigned int uint32;

class color32
{
public:
    union {
        struct { uint8 b, g, r, a; } c;
        uint32 i;
    };

    color32(uint32 value = 0) : i(value) {}
    color32(uint8 r, uint8 g, uint8 b, uint8 a = 255)
    {
        c.b = b;
        c.g = g;
        c.r = r;
        c.a = a;
    }
    uint8 get_red() const { return c.r; }
    uint8 get_green() const { return c.g; }
    uint8 get_blue() const { return c.b; }
    uint8 get_alpha() const { return c.a; }
    void set_alpha(uint8 value) { c.a = value; }
    const color32 &operator=(const color32 &value)
    {
        i = value.i;
        return *this;
    }
};

struct TextVTable {
    char padding[8];
    short adjustment;
    short reserved;
    void (*draw)(void *);
};

struct MultiLineString {
    TextVTable *vtable;
    char padding[0x3c];
    bool no_color;
    char padding2[3];
    color32 color;

    void Draw()
    {
        TextVTable *table = vtable;
        table->draw((char *)this + table->adjustment);
    }
};

struct FEMenu {
    char padding[0x20];
    color32 color;
    color32 color_high;
    color32 color_high_alt;
    char padding2[0x10];
    unsigned int flags;
};

class FEMenuEntry {
    int entry_num;
    FEMenuEntry *next;
    FEMenuEntry *previous;
    FEMenu *menu;
    bool highlight;
    bool disabled;
    char padding[2];
    void *ent;
    color32 high_ent_color;
    color32 norm_ent_color;
    MultiLineString *text;
    float highlight_intensity;
    float highlight_timer;
    int disabled_alpha;
    color32 special_color;
    color32 special_color_high;
    bool has_special_color;
    bool no_flash;
    char padding2[2];
    float special_scale;
    float special_scale_high;
    bool has_special_scale;

public:
    void Draw();
};

enum {
    FEMENU_HAS_COLOR_HIGH_ALT = 0x10,
    FEMENU_DONT_SKIP_DISABLED = 0x40,
    FEMENU_NO_FLASHING = 0x100,
    FEMENU_NORM_COLOR_NO_FLASH = 0x200
};

void FEMenuEntry::Draw()
{
    uint8 r, g, b, a;

    if (highlight && (!(menu->flags & FEMENU_DONT_SKIP_DISABLED) || !disabled))
    {
        color32 ch = menu->color_high;
        color32 c = menu->color;
        if (menu->flags & FEMENU_HAS_COLOR_HIGH_ALT)
            c = menu->color_high_alt;
        if (has_special_color)
        {
            c = special_color;
            ch = special_color_high;
        }

        if (menu->flags & FEMENU_NO_FLASHING || no_flash)
        {
            if (menu->flags & FEMENU_NORM_COLOR_NO_FLASH)
                text->color = c;
            else
                text->color = ch;
            if (disabled)
                text->color.set_alpha(disabled_alpha);
        }
        else
        {
            r = (int)(c.get_red() + (highlight_intensity + .5f) *
                (ch.get_red() - c.get_red()));
            g = (int)(c.get_green() + (highlight_intensity + .5f) *
                (ch.get_green() - c.get_green()));
            b = (int)(c.get_blue() + (highlight_intensity + .5f) *
                (ch.get_blue() - c.get_blue()));
            a = ch.get_alpha();
            text->color = color32(r, g, b, a);
        }
    }
    else
    {
        if (has_special_color)
            text->color = special_color;
        else
            text->color = menu->color;
        if (disabled)
            text->color.set_alpha(disabled_alpha);
    }

    text->Draw();
}
